"180\" r=\"7\"/><circle cx=\"530\" cy=\"180\" r=\"7\"/><circle cx=\"555\" cy=\"180\" r=\"7\"/>\n</g>\n<text x=\"105\" y=\"30\" font-size=\"16\" text-anchor=\"middle\" fill=\"#166534\" font-weight=\"bold\">Горы</text>\n<text x=\"300\" y=\"30\" font-size=\"16\" text-anchor=\"middle\" fill=\"#a16207\" font-weight=\"bold\">Деревня</text>\n<text x=\"495\" y=\"30\" font-size=\"16\" text-anchor=\"middle\" fill=\"#b91c1c\" font-weight=\"bold\">Город</text>\n<text x=\"105\" y=\"240\" font-size=\"15\" text-anchor=\"middle\" fill=\"#0f172a\">2 человека</text>\n<text x=\"300\" y=\"240\" font-size=\"15\" text-anchor=\"middle\" fill=\"#0f172a\">8 человек</text>\n<text x=\"495\" y=\"240\" font-size=\"15\" text-anchor=\"middle\" fill=\"#0f172a\">30 человек</text>\n<text x=\"105\" y=\"265\" font-size=\"15\" text-anchor=\"middle\" fill=\"#166534\" font-weight=\"bold\">плотность НИЗКАЯ</text>\n<text x=\"300\" y=\"265\" font-size=\"15\" text-anchor=\"middle\" fill=\"#a16207\" font-weight=\"bold\">плотность СРЕДНЯЯ</text>\n<text x=\"495\" y=\"265\" font-size=\"15\" text-anchor=\"middle\" fill=\"#b91c1c\" font-weight=\"bold\">плотность ВЫСОКАЯ</text>\n<text x=\"300\" y=\"292\" font-size=\"14\" text-anchor=\"middle\" fill=\"#334155\">плотность = жители : площадь</text>\n</svg>"
